#include "chronus1/emulator.h"
#include "chronus1/isa.h"
#include <cmath>
#include <cstring>
#include <filesystem>
#include <iostream>
#include <vector>
using namespace chronus1;
static void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}template<class F>static void traps(F f,TrapCode c){try{f();throw std::runtime_error("expected trap");}catch(const Trap&t){require(t.code==c,"wrong trap");}}
static Binary bin(std::vector<uint32_t> code,uint32_t mem=1024){return Binary{1,0,0,0,mem,std::move(code)};}
static float flt(uint32_t v){float x;std::memcpy(&x,&v,4);return x;}
static void test_decode(){std::vector<Opcode> ops={Opcode::NOP,Opcode::MOV,Opcode::MOVI,Opcode::ADD,Opcode::SUB,Opcode::MUL,Opcode::FMA,Opcode::LOAD,Opcode::STORE,Opcode::LLOAD,Opcode::LSTORE,Opcode::BARRIER,Opcode::BRA,Opcode::BRAZ,Opcode::BRANZ,Opcode::GET_GID,Opcode::GET_LID,Opcode::GET_GSIZE,Opcode::GET_LSIZE,Opcode::EXIT};for(auto o:ops){uint32_t raw;if(o==Opcode::MOVI||o==Opcode::LOAD||o==Opcode::LLOAD)raw=encode_i(o,1,o==Opcode::MOVI?0:2,3);else if(o==Opcode::STORE||o==Opcode::LSTORE)raw=encode_i(o,1,2,3);else if(o==Opcode::BRA||o==Opcode::BRAZ||o==Opcode::BRANZ)raw=encode_b(o,o==Opcode::BRA?0:1,0);else if(o==Opcode::BARRIER)raw=encode_s(o,1,0);else if(o==Opcode::GET_GID||o==Opcode::GET_LID||o==Opcode::GET_GSIZE||o==Opcode::GET_LSIZE)raw=encode_s(o,1,2);else if(o==Opcode::NOP||o==Opcode::EXIT)raw=encode_r(o);else raw=encode_r(o,1,o==Opcode::MOV?2:1,(o==Opcode::ADD||o==Opcode::SUB||o==Opcode::MUL||o==Opcode::FMA)?2:0,o==Opcode::FMA?3:0);require(decode(raw).op==o,"decode mismatch");}traps([]{decode(7u<<26);},TrapCode::IllegalOpcode);traps([]{decode(encode_r(Opcode::NOP,1));},TrapCode::MalformedEncoding);}
static void test_add_store(){auto b=bin({encode_i(Opcode::MOVI,1,0,2),encode_i(Opcode::MOVI,2,0,2),encode_r(Opcode::ADD,3,1,2),encode_i(Opcode::STORE,3,0,0),encode_r(Opcode::EXIT)});auto path=std::filesystem::temp_directory_path()/"chronus1-add.chronus";write_binary(path,b);auto loaded=load_binary(path);std::filesystem::remove(path);Emulator e(loaded,1024);e.dispatch({});require(e.global_memory().read32(0)==4,"2+2 store failed");}
static void test_traps(){traps([]{Emulator e(bin({encode_i(Opcode::LOAD,1,0,2),encode_r(Opcode::EXIT)}),1024);e.dispatch({});},TrapCode::Misaligned);traps([]{Emulator e(bin({encode_i(Opcode::MOVI,1,0,1020),encode_i(Opcode::LOAD,2,1,8),encode_r(Opcode::EXIT)}),1024);e.dispatch({});},TrapCode::OutOfBounds);traps([]{Emulator e(bin({encode_b(Opcode::BRA,0,-1)}),1024);Dispatch d;d.instruction_budget=8;e.dispatch(d);},TrapCode::BudgetExhausted);traps([]{std::vector<uint32_t> c={encode_s(Opcode::GET_LID,1,0),encode_b(Opcode::BRAZ,1,1),encode_s(Opcode::BARRIER,1,0),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);Dispatch d;d.global={2,1,1};d.local={2,1,1};e.dispatch(d);},TrapCode::InvalidEarlyExit);}
static void test_divergence(){std::vector<uint32_t> c={encode_s(Opcode::GET_LID,1,0),encode_b(Opcode::BRAZ,1,2),encode_i(Opcode::MOVI,2,0,1),encode_b(Opcode::BRA,0,1),encode_i(Opcode::MOVI,2,0,2),encode_i(Opcode::MOVI,3,0,4),encode_r(Opcode::MUL,4,1,3),encode_i(Opcode::STORE,2,4,0),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);Dispatch d;d.global={4,1,1};d.local={4,1,1};e.dispatch(d);require(e.global_memory().read32(0)==2,"taken path failed");for(int i=1;i<4;i++)require(e.global_memory().read32(i*4)==1,"fallthrough path failed");}
static void test_partial_barrier(){std::vector<uint32_t> c={encode_s(Opcode::GET_GID,1,0),encode_i(Opcode::MOVI,2,0,4),encode_r(Opcode::MUL,3,1,2),encode_s(Opcode::BARRIER,1,0),encode_i(Opcode::STORE,1,3,0),encode_r(Opcode::EXIT)};Emulator e(bin(c,4096),4096);Dispatch d;d.global={35,1,1};d.local={32,1,1};e.dispatch(d);for(int i=0;i<35;i++)require(e.global_memory().read32(i*4)==uint32_t(i),"partial barrier result failed");}
static std::vector<uint32_t> matmul(){std::vector<uint32_t>c;auto R=[&](Opcode o,int d=0,int a=0,int b=0,int x=0){c.push_back(encode_r(o,d,a,b,x));};auto I=[&](Opcode o,int d,int a,int v){c.push_back(encode_i(o,d,a,v));};auto S=[&](Opcode o,int d,int x){c.push_back(encode_s(o,d,x));};S(Opcode::GET_GID,1,0);S(Opcode::GET_GID,2,1);S(Opcode::GET_LID,3,0);S(Opcode::GET_LID,4,1);I(Opcode::MOVI,5,0,2);I(Opcode::MOVI,6,0,4);I(Opcode::MOVI,7,0,64);I(Opcode::MOVI,8,0,128);I(Opcode::MOVI,14,0,1);R(Opcode::MUL,10,4,5);R(Opcode::ADD,10,10,3);R(Opcode::MUL,10,10,6);R(Opcode::MUL,11,2,5);R(Opcode::ADD,11,11,1);R(Opcode::MUL,11,11,6);I(Opcode::LOAD,12,11,0);I(Opcode::LSTORE,12,10,0);R(Opcode::ADD,11,11,7);I(Opcode::LOAD,12,11,0);I(Opcode::LSTORE,12,10,32);S(Opcode::BARRIER,1,0);I(Opcode::MOVI,9,0,0);I(Opcode::MOVI,13,0,0);I(Opcode::MOVI,15,0,2);int loop=c.size();R(Opcode::MUL,16,4,5);R(Opcode::ADD,16,16,13);R(Opcode::MUL,16,16,6);I(Opcode::LLOAD,17,16,0);R(Opcode::MUL,18,13,5);R(Opcode::ADD,18,18,3);R(Opcode::MUL,18,18,6);I(Opcode::LLOAD,19,18,32);R(Opcode::FMA,9,17,19,9);R(Opcode::ADD,13,13,14);R(Opcode::SUB,15,15,14);c.push_back(encode_b(Opcode::BRANZ,15,loop-int(c.size())-1));R(Opcode::MUL,20,2,5);R(Opcode::ADD,20,20,1);R(Opcode::MUL,20,20,6);R(Opcode::ADD,20,20,8);I(Opcode::STORE,9,20,0);R(Opcode::EXIT);return c;}
static void test_matmul_replay(){auto run=[](){Emulator e(bin(matmul(),256),256);float a[4]={1,2,3,4},b[4]={5,6,7,8};e.global_memory().write_bytes(0,a,sizeof a);e.global_memory().write_bytes(64,b,sizeof b);Dispatch d;d.global={2,2,1};d.local={2,2,1};e.dispatch(d);std::vector<uint32_t>o;for(int i=0;i<4;i++)o.push_back(e.global_memory().read32(128+i*4));return o;};auto x=run(),y=run();require(x==y,"replay not bit exact");float expected[4]={19,22,43,50};for(int i=0;i<4;i++)require(std::fabs(flt(x[i])-expected[i])<1e-6f,"matmul mismatch");}
int main(){try{test_decode();test_add_store();test_traps();test_divergence();test_partial_barrier();test_matmul_replay();std::cout<<"Chronus-1 emulator acceptance: PASS\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
